<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';
pembinaan_require_access();
$id=max(0,(int)($_GET['id']??0));
$errors=[];$success='';
if($_SERVER['REQUEST_METHOD']==='POST') {
 require_valid_csrf();
 if(!pembinaan_can_manage()) deny_access();
 $action=(string)($_POST['action']??'');
 if($action==='status') {
  $newStatus=(string)($_POST['status']??'');
  if(!in_array($newStatus,['proses','selesai','dibatalkan'],true)) $errors[]='Status tujuan tidak valid.';
  if(!$errors) {
   $q=$pdo->prepare('SELECT id,status,siswa_id FROM pembinaan_siswa WHERE id=? LIMIT 1');$q->execute([$id]);$cur=$q->fetch();
   if(!$cur) $errors[]='Data pembinaan tidak ditemukan.';
   else {
    $allowed=(($cur['status']==='direncanakan' && in_array($newStatus,['proses','dibatalkan'],true)) || ($cur['status']==='proses' && in_array($newStatus,['selesai','dibatalkan'],true)));
    if(!$allowed) $errors[]='Perubahan status tidak mengikuti alur yang diizinkan.';
    else {
     $u=$pdo->prepare('UPDATE pembinaan_siswa SET status=? WHERE id=? AND status=?');$u->execute([$newStatus,$id,$cur['status']]);
     if($u->rowCount()!==1) $errors[]='Status tidak berubah. Silakan muat ulang halaman.';
     else {pembinaan_audit($pdo,'STATUS_CHANGE',$id,'Status pembinaan #'.$id.' berubah dari '.$cur['status'].' menjadi '.$newStatus);$success='Status pembinaan berhasil diperbarui.';}
    }
   }
  }
 }
}
$st=$pdo->prepare("SELECT p.*,s.nis,s.nisn,s.nama,mk.nama kelas,g.nama petugas,jp.kode pelanggaran_kode,jp.nama pelanggaran_nama,ps.poin pelanggaran_poin FROM pembinaan_siswa p JOIN siswa s ON s.id=p.siswa_id LEFT JOIN guru g ON g.id=p.petugas_id LEFT JOIN pelanggaran_siswa ps ON ps.id=p.pelanggaran_id LEFT JOIN jenis_pelanggaran jp ON jp.id=ps.jenis_pelanggaran_id LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=p.tahun_pelajaran_id AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE p.id=? LIMIT 1");$st->execute([$id]);$row=$st->fetch();if(!$row){http_response_code(404);exit('Data pembinaan tidak ditemukan.');}
$tapel=$pdo->prepare('SELECT nama FROM tahun_pelajaran WHERE id=?');$tapel->execute([(int)$row['tahun_pelajaran_id']]);$tapelNama=$tapel->fetchColumn()?:'-';
$hist=$pdo->prepare("SELECT p.id,p.tanggal,p.jenis,p.status,p.hasil FROM pembinaan_siswa p WHERE p.siswa_id=? AND p.tahun_pelajaran_id=? ORDER BY p.tanggal DESC,p.id DESC");$hist->execute([(int)$row['siswa_id'],(int)$row['tahun_pelajaran_id']]);$history=$hist->fetchAll();
$adjustAlready=$pdo->prepare("SELECT id FROM pelanggaran_poin_penyesuaian WHERE siswa_id=? AND tahun_pelajaran_id=? AND tindakan LIKE ? LIMIT 1");$adjustAlready->execute([(int)$row['siswa_id'],(int)$row['tahun_pelajaran_id'],'Pembinaan #'.$id.'%']);$alreadyAdjusted=(bool)$adjustAlready->fetchColumn();
$canApplyReduction=(pembinaan_can_reduce_points() && $row['status']==='selesai' && (int)$row['rekomendasi_pengurangan_poin']>0 && trim((string)($row['hasil']??''))!=='' && !$alreadyAdjusted);
$page_title='Detail Pembinaan';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
<main class="main"><header class="topbar"><div class="topbar-title">Detail Pembinaan</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><style>.pb-detail{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(280px,.75fr);gap:18px}.pb-box{background:#fff;border:1px solid #e2e8f0;border-radius:15px;padding:18px}.pb-title{font-size:19px;font-weight:850;margin:0 0 4px}.pb-meta{color:#64748b;font-size:12px}.pb-field{margin-top:16px}.pb-field .lbl{font-size:11px;font-weight:850;color:#64748b;text-transform:uppercase;letter-spacing:.03em}.pb-field .val{margin-top:5px;white-space:pre-wrap;line-height:1.55}.pb-status{display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:850;padding:5px 8px;border-radius:999px}.pb-status-proses{background:#ffedd5;color:#9a3412}.pb-status-selesai{background:#dcfce7;color:#166534}.pb-status-plan{background:#e0e7ff;color:#3730a3}.pb-status-batal{background:#f1f5f9;color:#475569}@media(max-width:800px){.pb-detail{grid-template-columns:1fr}}</style>
<div class="page-header"><div><h1><i class="bi bi-person-check-fill"></i> Detail Pembinaan</h1><p><?=e($tapelNama)?> · <?=e($row['tanggal'])?></p></div><div class="page-header-actions"><a class="btn btn-secondary" href="<?=BASE_URL?>pembinaan/index.php"><i class="bi bi-arrow-left"></i> Kembali</a></div></div>
<?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><?php if($success):?><div class="alert alert-success"><i class="bi bi-check-circle"></i> <?=e($success)?></div><?php endif;?>
<div class="pb-detail"><div class="pb-box"><h2 class="pb-title"><?=e($row['nama'])?></h2><div class="pb-meta">NIS <?=e($row['nis'])?><?=!empty($row['nisn'])?' · NISN '.e($row['nisn']):''?> · Kelas <?=e($row['kelas']??'Belum ditempatkan')?></div><div style="margin-top:13px"><span class="pb-status <?=e(pembinaan_status_class($row['status']))?>"><?=e(pembinaan_status_label($row['status']))?></span> <?php if((int)$row['melibatkan_ortu']===1):?><span class="pb-status pb-status-plan"><i class="bi bi-people-fill"></i> Orang tua terlibat</span><?php endif;?></div>
<?php if(pembinaan_can_manage()):?><div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap"><?php if($row['status']==='direncanakan'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="status" value="proses"><button class="btn btn-primary btn-sm"><i class="bi bi-play-circle"></i> Mulai Pembinaan</button></form><?php elseif($row['status']==='proses'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="status" value="selesai"><button class="btn btn-primary btn-sm" onclick="return confirm('Tandai pembinaan ini sebagai selesai?')"><i class="bi bi-check2-circle"></i> Tandai Selesai</button></form><?php endif;?></div><?php endif;?><?php foreach([['Jenis','Pembinaan'],['Tanggal',$row['tanggal'].(!empty($row['waktu'])?' · '.substr($row['waktu'],0,5):'')],['Masalah / Konteks',$row['masalah']],['Tindakan',$row['tindakan']?:'-'],['Hasil',$row['hasil']?:'-'],['Tindak Lanjut',$row['tindak_lanjut']?:'-'],['Petugas',$row['petugas']?:'Sistem'],['Rekomendasi Pengurangan Poin',(int)$row['rekomendasi_pengurangan_poin'].' poin'] ] as $f):?><div class="pb-field"><div class="lbl"><?=e($f[0])?></div><div class="val"><?=e((string)$f[1])?></div></div><?php endforeach;?><?php if(!empty($row['pelanggaran_nama'])):?><div class="pb-field"><div class="lbl">Pelanggaran Terkait</div><div class="val"><?=e($row['pelanggaran_kode'])?> · <?=e($row['pelanggaran_nama'])?> (+<?=e($row['pelanggaran_poin'])?> poin)</div></div><?php endif;?></div>
<div class="pb-box"><h2 class="pb-title">Riwayat Pembinaan Siswa</h2><div class="pb-meta">Tahun Pelajaran <?=e($tapelNama)?></div><div class="table-responsive" style="margin-top:12px"><table class="data-table"><thead><tr><th>Tanggal</th><th>Jenis</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=e($h['tanggal'])?></td><td><?=e($h['jenis'])?></td><td><?=e(pembinaan_status_label($h['status']))?></td><td><a class="btn btn-secondary btn-sm" href="<?=BASE_URL?>pembinaan/detail.php?id=<?=$h['id']?>"><i class="bi bi-eye"></i></a></td></tr><?php endforeach;?></tbody></table></div><?php if($canApplyReduction):?><div class="alert alert-success" style="margin-top:14px"><i class="bi bi-check2-circle"></i> Pembinaan ini sudah selesai, memiliki hasil evaluasi, dan memiliki rekomendasi pengurangan <?=number_format((int)$row['rekomendasi_pengurangan_poin'])?> poin.</div><a class="btn btn-primary" href="<?=BASE_URL?>pelanggaran/detail.php?id=<?=(int)$row['siswa_id']?>"><i class="bi bi-arrow-down-circle"></i> Terapkan Pengurangan Poin</a><?php elseif($alreadyAdjusted):?><div class="alert alert-info" style="margin-top:14px"><i class="bi bi-check-circle"></i> Pengurangan poin untuk pembinaan ini sudah diterapkan.</div><?php else:?><div class="alert alert-info" style="margin-top:14px"><i class="bi bi-arrow-repeat"></i> Jika pembinaan menghasilkan perbaikan perilaku, setelah status <strong>Selesai</strong> dan hasil evaluasi diisi, BK/Kesiswaan dapat menerapkan pengurangan poin melalui modul Pelanggaran.</div><?php endif;?></div></div>
</section></main><?php require_once __DIR__.'/../layouts/footer.php'; ?>
